package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayerRulesTest {

    private static final String DOMAIN = "com.example.payment.domain..";
    private static final String APPLICATION = "com.example.payment.application..";
    private static final String INFRASTRUCTURE = "com.example.payment.infrastructure..";
    private static final String APP = "com.example.payment.app..";

    private static final String[] TECHNICAL = {
        "org.springframework..", "java.io..", "java.nio..", "java.net..", "java.sql..",
        "javax..", "jakarta..", "com.fasterxml..",
    };

    @ArchTest
    static final ArchRule domainDependsOnNoOtherLayer = noClasses().that().resideInAPackage(DOMAIN)
            .should().dependOnClassesThat().resideInAnyPackage(APPLICATION, INFRASTRUCTURE, APP);

    @ArchTest
    static final ArchRule applicationDependsOnlyOnDomain = noClasses().that().resideInAPackage(APPLICATION)
            .should().dependOnClassesThat().resideInAnyPackage(INFRASTRUCTURE, APP);

    @ArchTest
    static final ArchRule infrastructureStaysBelowApp = noClasses().that().resideInAPackage(INFRASTRUCTURE)
            .should().dependOnClassesThat().resideInAPackage(APP);

    @ArchTest
    static final ArchRule domainHasNoTechnicalDetails = noClasses().that().resideInAPackage(DOMAIN)
            .should().dependOnClassesThat().resideInAnyPackage(TECHNICAL);

    @ArchTest
    static final ArchRule applicationHasNoTechnicalDetails = noClasses().that().resideInAPackage(APPLICATION)
            .should().dependOnClassesThat().resideInAnyPackage(TECHNICAL);
}
E
